(async () => { const app = window.__CITY_APP, C = window.CITY, t = C.worldFromLatLon(43.6466, -79.3895); if(!document.body.classList.contains('hud-minimized'))document.getElementById('btn-toggle-hud').click();
app.cameraSystem.cinema = null; const sleep = (ms) => new Promise((r) => setTimeout(r, ms)); const S = app.streetcars, o = { x: 0, y: 0, z: 0, yaw: 0 };
let best = null, bd = 1e9;
for (const c of S.cars) { S.sample(c.track, c.s - 15, o); if (o.y < -1) continue; if (!(Math.abs(Math.sin(o.yaw)) > 0.7)) continue; if (c.route && (!/^504/.test(c.route.sign[0]) || (-1 >= 0 && c.route.dir !== -1))) continue; const d = Math.hypot(o.x - t.x, o.z - t.z); if (d < bd) { bd = d; best = c; } }
console.log('[shot] king-504 streetcar ' + (best.route ? best.route.sign.join(' / ') : '(no route)') + ' ' + Math.round(bd) + ' m from target');
S.sample(best.track, best.s, o); app.teleportTo(o.x + 25, o.z + 25, 0); await sleep(2500);
app.cameraSystem.cinema = () => { const n = best.sections[0], m = best.sections[2]; const fx = Math.sin(n.yaw), fz = Math.cos(n.yaw), rx = -fz, rz = fx;
return { pos: [n.x + fx * 16 + rx * 5.5, n.y + 1.6, n.z + fz * 16 + rz * 5.5], look: [m.x, m.y + 2.2, m.z], fov: 50 }; }; })()

